{"packet_id": "D067-03", "doc_id": "D067", "jurisdiction": "NJ", "category": "just_cause_eviction", "lifecycle": "enacted", "title": "New Jersey Anti-Eviction Act grounds for eviction", "requirement": "A landlord may remove a residential tenant only for one of the statutory grounds listed in the Anti-Eviction Act, and must serve the Notice to Quit required for that ground before filing suit.", "key_value": null, "coverage_conditions": "Most residential rental properties: single-family homes, mobile homes and mobile home park land, apartment buildings and complexes, and rooming and boarding homes.", "applicability": {"built_on_or_before": null, "built_after": null, "date_basis": null, "min_units": null, "max_units": null, "owner_dependent": true, "other": null}, "exemptions": "May not apply to two- or three-unit owner-occupied premises with two or fewer rental units; hotel, motel or guest-house stays by transient or seasonal tenants; units held in trust for a developmentally disabled immediate family member.", "penalty": null, "effective_date": null, "citation": "N.J.S.A. 2A:18-61.1", "quoted_span": "The Anti-Eviction Act applies to most residential rental properties including single-family
homes, mobile homes and land in a mobile home park, apartment buildings, and complexes. This
law also applies to rooming and boarding homes (N.J.S.A. 2A:18-53 to -84).", "interaction": null, "confidence": 0.75, "conflict_flag": false, "conflict_note": null}
{"packet_id": "D067-03", "doc_id": "D067", "jurisdiction": "NJ", "category": "just_cause_eviction", "lifecycle": "enacted", "title": "Relocation assistance for certain Anti-Eviction Act evictions", "requirement": "A tenant evicted so the landlord can correct an illegal occupancy is entitled to relocation assistance equal to six times the monthly rent, paid by the landlord at least five days before removal.", "key_value": "6 times monthly rent", "coverage_conditions": "Tenants evicted under the health and safety, removal-from-rental-market and illegal occupancy grounds; the six-times-rent amount applies to tenants evicted for correction of an illegal occupancy.", "applicability": {"built_on_or_before": null, "built_after": null, "date_basis": null, "min_units": null, "max_units": null, "owner_dependent": false, "other": null}, "exemptions": null, "penalty": "Unpaid relocation assistance accrues interest at 18% per year and is a lien on the property, enforceable by filing a lien statement with the county clerk or registrar.", "effective_date": null, "citation": "N.J.S.A. 2A:18-61.1(g)", "quoted_span": "Any tenant evicted under G 3) (illegal occupancy) is entitled to relocation assistance in
